/** Shared formatting, escaping and icon helpers. */
export const LETTERS = ['A', 'B', 'C', 'D', 'E'];
export const html = value => value === undefined || value === null ? '' : String(value);

export function escapeHtml(value) {
  if (value === undefined || value === null) return '';
  return String(value).replace(/[&<>"']/g, char => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[char]);
}

/**
 * Render question-bank content safely while preserving source code formatting.
 * Plain text is escaped; only markup generated by this function is inserted.
 */
const CODE_START = /^(?:<!doctype\b|<\/?(?:html|head|body|div|p|button|script|ion-[\w-]+|template|my-component|router-view)\b|(?:import|export)\s|(?:const|let|var)\s+[\w$]+\s*=|function\s+[\w$]+(?:<[^>]+>)?\s*\(|class\s+[\w$]+\b|(?:public|private|protected)\s|(?:SELECT|INSERT|UPDATE|DELETE|CREATE|ALTER)\b|echo\s*<|for\s*\(|if\s*\(|new\s+(?:Vue|[A-Z])|Vue\.|app\.mount\s*\(|createApp\s*\(|\$\w+\s*=|[A-Za-z_$][\w$]*\s*\([^)]*\)\s*\{)/i;
const CODE_CONTINUATION = /^(?:\{|\}|\]|\)|\);|,|\.|<\/?[A-Za-z][^>]*>|[A-Za-z][\w-]*>|[A-Za-z_$][\w$.]*\s*\(|return\b|this\.|console\.|\.then\b|\.catch\b|data\s*\(|methods\s*:|template\s*:|routes\b|history\s*:|path\s*:|name\s*:|component\s*:|el\s*:|router\s*,|v-(?:if|else|for|on|bind|model)\b|\/?script\b|\/\/|\/\*|\*\/|else\b|catch\b|finally\b)/i;

function isCodeStart(line) {
  const value = line.trim();
  return !!value && (CODE_START.test(value) || /^\s*(?:[A-Za-z_$][\w$]*\s*=\s*[^=]|\{\s*$|\}\s*;?$)/.test(line));
}

function isCodeContinuation(line) {
  if (!line.trim()) return true;
  if (/^\s{2,}\S/.test(line)) return true;
  const value = line.trim();
  return CODE_CONTINUATION.test(value) || /[{};]\s*$/.test(value) || /^['"`][^'"`]*['"`],?$/.test(value);
}

function dedentCode(lines) {
  const nonEmpty = lines.filter(line => line.trim());
  if (!nonEmpty.length) return lines;
  const indents = nonEmpty.map(line => (line.match(/^[ \t]*/) || [''])[0].replace(/\t/g, '  ').length);
  const minimum = Math.min(...indents);
  return lines.map(line => {
    if (!line.trim()) return '';
    let remaining = minimum;
    let index = 0;
    while (index < line.length && remaining > 0 && (line[index] === ' ' || line[index] === '\t')) {
      remaining -= line[index] === '\t' ? 2 : 1;
      index++;
    }
    return line.slice(index);
  });
}

function detectCodeLang(code) {
  const trimmed = String(code || '').trim();
  if (!trimmed) return 'Kode';
  if (/^\s*(?:<!doctype|<html|<div|<script|<template|<ion-|<my-component)/i.test(trimmed) || /v-(?:on|if|for|bind|model)|\{\{\s*[^}]+\s*\}\}/.test(trimmed)) return 'HTML / Vue';
  if (/^\s*(?:SELECT|INSERT|UPDATE|DELETE|CREATE|ALTER|DROP)\b/i.test(trimmed)) return 'SQL';
  if (/^\s*(?:zone\s+"|\/etc\/|systemctl\b|firewall-cmd\b|yum\b|useradd\b|usermod\b|#)/i.test(trimmed)) return 'Konfigurasi / CLI';
  if (/:\s*(?:string|number|boolean|any|void)\b|<[A-Z]\w*>/.test(trimmed)) return 'TypeScript';
  if (/\b(?:const|let|var|function|console\.log|createApp|VueRouter|=>)\b/.test(trimmed)) return 'JavaScript';
  return 'Kode';
}

function buildCodeBlockMarkup(code, inlineBlocks = false) {
  const text = String(code ?? '');
  const lineCount = text.split('\n').length;
  if (inlineBlocks) {
    return `<span class="code-block code-block-inline"><code>${escapeHtml(text)}</code></span>`;
  }
  if (lineCount < 2) {
    return `<pre class="code-block"><code>${escapeHtml(text)}</code></pre>`;
  }
  const lang = detectCodeLang(text);
  return `<div class="code-block-wrap"><div class="code-block-head"><span>${escapeHtml(lang)}</span><span>${lineCount} baris</span></div><pre class="code-block"><code>${escapeHtml(text)}</code></pre></div>`;
}

const EXCLUDED_DOTTED = /^(?:www\.|https?:\/\/)|(?:\.(?:com|org|net|id|edu|gov|io|co|uk|au)\b)|^(?:[A-Za-z]\.[A-Za-z])$/i;
const CLI_PROSE_STOP = /\b(?:pada|akan|adalah|untuk|yang|dengan|atau|dan|di|ke|dari|oleh|sebagai|dalam|jika|maka|yaitu|yakni|sedangkan|digunakan|berfungsi|bertujuan|merupakan|dapat|harus|tidak)\b/i;

function renderInlineCode(text) {
  const pattern = /(`[^`\n]+`|\{\{\s*[^{}\n]+\s*\}\}|\b[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+(?:\([^()\n<>]*\))?|\b[A-Za-z_$][\w$]*<[^<>\n]+>\([^()\n<>]*\)|\b(?:console|Math|JSON|Object|Array|String|Number|Promise|Vue|VueRouter|createApp|echo|COUNT|SUM|AVG|MIN|MAX|CHAR|VARCHAR|VCHAR|CHR|KARAKTER)\s*\([^()\n<>]*\)|\b(?:npm\s+(?:run|install|create)|ionic\s+start|vue\s+create|systemctl\s+(?:start|stop|restart|enable|disable|status)|firewall-cmd|yum\s+(?:install|remove|update)|useradd|usermod|userdel|gpasswd)\b(?:\s+(?:--?[A-Za-z0-9_-]+|[A-Za-z0-9_./:@-]+|<[A-Za-z0-9_-]+>)){0,4}|\b(?:SELECT|INSERT|UPDATE|DELETE|CREATE|ALTER|DROP|WHERE|VALUES|FROM|SET)\b|\b(?:const|let|var)\s+[A-Za-z_$][\w$]*|\bfunction\s+[A-Za-z_$][\w$]*\s*(?:<[^<>\n]+>)?\(|\bclass\s+[A-Z][\w$]*\s*(?:\{|extends\b|implements\b)|\b[A-Za-z_$][\w$]*(?:\+\+|--)|\bv-(?:on|if|else|for|bind|model)(?::[\w-]+)?\b)/g;
  let result = '';
  let last = 0;
  for (const match of text.matchAll(pattern)) {
    const rawToken = match[0];
    const index = match.index ?? 0;
    let token = rawToken.trim();
    if (EXCLUDED_DOTTED.test(token)) {
      result += escapeHtml(text.slice(last, index + rawToken.length));
      last = index + rawToken.length;
      continue;
    }
    if (!token.startsWith('`')) {
      const proseStop = token.match(CLI_PROSE_STOP);
      if (proseStop && typeof proseStop.index === 'number') {
        token = token.slice(0, proseStop.index).trim();
      }
    }
    if (!token) {
      result += escapeHtml(text.slice(last, index + rawToken.length));
      last = index + rawToken.length;
      continue;
    }
    const leadingSpaces = rawToken.slice(0, rawToken.indexOf(token[0]));
    result += escapeHtml(text.slice(last, index) + leadingSpaces);
    const value = token.startsWith('`') && token.endsWith('`') ? token.slice(1, -1) : token;
    result += `<code class="inline-code">${escapeHtml(value)}</code>`;
    last = index + leadingSpaces.length + token.length;
  }
  return result + escapeHtml(text.slice(last));
}

function decodeHtmlEntities(value) {
  const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: '\u00a0' };
  return String(value).replace(/&(#x[\da-f]+|#\d+|amp|lt|gt|quot|apos|nbsp);/gi, (entity, key) => {
    const normalized = key.toLowerCase();
    if (normalized in named) return named[normalized];
    const codePoint = normalized.startsWith('#x') ? parseInt(normalized.slice(2), 16) : parseInt(normalized.slice(1), 10);
    return Number.isFinite(codePoint) && codePoint >= 0 && codePoint <= 0x10ffff ? String.fromCodePoint(codePoint) : entity;
  });
}

function plainTextFromMarkup(value) {
  return decodeHtmlEntities(String(value).replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();
}

function tableMarkupFromHtml(rawTable) {
  const captionMatch = rawTable.match(/<caption\b[^>]*>([\s\S]*?)<\/caption>/i);
  const rows = [...rawTable.matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)].map(match => {
    const cells = [...match[1].matchAll(/<(th|td)\b[^>]*>([\s\S]*?)<\/\1>/gi)];
    return { header: cells.some(cell => cell[1].toLowerCase() === 'th'), values: cells.map(cell => plainTextFromMarkup(cell[2])) };
  }).filter(row => row.values.length);
  if (!rows.length) return `<div class="rich-html-block">${escapeHtml(plainTextFromMarkup(rawTable))}</div>`;
  const headerIndex = rows.findIndex(row => row.header);
  const headers = headerIndex >= 0 ? rows[headerIndex].values : rows[0].values;
  const body = rows.filter((_, index) => index !== headerIndex && (headerIndex >= 0 || index > 0));
  return `<div class="question-table-wrap" role="region" aria-label="Tabel soal" tabindex="0"><table class="question-data-table">${captionMatch ? `<caption>${escapeHtml(plainTextFromMarkup(captionMatch[1]))}</caption>` : ''}<thead><tr>${headers.map(cell => `<th scope="col">${escapeHtml(cell)}</th>`).join('')}</tr></thead><tbody>${body.map(row => `<tr>${headers.map((_, index) => `<td>${escapeHtml(row.values[index] ?? '')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}

function prepareRichSource(value, inlineBlocks = false) {
  let raw = String(value ?? '').replace(/\r\n?/g, '\n');
  const blocks = [];
  const addBlock = (markup, type) => {
    const marker = `__RICH_BLOCK_${blocks.length}__`;
    blocks.push({ marker, html: markup, type });
    return `\n${marker}\n`;
  };
  // Ekstrak <pre> lebih dulu agar tag pemformatan mentah (<b>/<i>) di dalamnya bisa dibersihkan tanpa merusak entitas kode.
  raw = raw.replace(/<pre\b[^>]*>([\s\S]*?)<\/pre>/gi, (_match, content) => {
    const cleaned = content
      .replace(/<\/?(?:code|b|i|strong|em|u)\b[^>]*>/gi, '')
      .replace(/^\n|\n$/g, '');
    const code = decodeHtmlEntities(cleaned);
    return addBlock(buildCodeBlockMarkup(code, inlineBlocks), 'code');
  });
  let source = decodeHtmlEntities(raw);
  source = source.replace(/<table\b[^>]*>[\s\S]*?<\/table>/gi, table => addBlock(tableMarkupFromHtml(table), 'table'));
  return { source, blocks };
}

const SAFE_MARKUP_TAGS = new Set(['b', 'strong', 'i', 'em', 'u', 'sup', 'sub', 'br', 'code', 'ul', 'ol', 'li', 'p', 'div', 'span']);
function renderSafeMarkup(text, inlineBlocks = false) {
  const tokens = String(text).split(/(<\/?[A-Za-z][\w-]*(?:\s+[^<>]*?)?\s*\/?>)/g);
  let insideCode = false;
  return tokens.map(token => {
    const tag = token.match(/^<\s*(\/?)\s*([A-Za-z][\w-]*)\b[^>]*>$/);
    if (tag) {
      const closing = Boolean(tag[1]);
      const name = tag[2].toLowerCase();
      if (SAFE_MARKUP_TAGS.has(name)) {
        if (inlineBlocks && ['p', 'div', 'ul', 'ol'].includes(name)) {
          const hasAttributes = /^<\s*[A-Za-z][\w-]*\s+[^>]+>$/.test(token);
          return hasAttributes ? `<code class="inline-code">${escapeHtml(token)}</code>` : '';
        }
        if (inlineBlocks && name === 'li') return closing ? '<br>' : '';
        if (name === 'code') {
          insideCode = !closing;
          return closing ? '</code>' : '<code class="inline-code">';
        }
        if (name === 'br') return '<br>';
        return closing ? `</${name}>` : `<${name}>`;
      }
      return insideCode ? escapeHtml(token) : `<code class="inline-code">${escapeHtml(token)}</code>`;
    }
    return insideCode ? escapeHtml(token) : renderInlineCode(token);
  }).join('');
}

function renderParagraph(lines, inlineBlocks = false) {
  if (!lines.length) return '';
  const text = lines.join('\n').trim();
  if (!text) return '';
  if (!text.includes('\n') && /^(?:echo\s*<|[A-Za-z_$][\w$]*(?:\.[\w$]+)*\([^)]*\)|(?:npm|ionic|vue)\s+)/i.test(text)) {
    return inlineBlocks ? `<span class="rich-inline-text"><code class="inline-code">${escapeHtml(text)}</code></span>` : `<p class="rich-paragraph"><code class="inline-code">${escapeHtml(text)}</code></p>`;
  }
  const content = text.split('\n').map(line => renderSafeMarkup(line, inlineBlocks)).join('<br>');
  if (!inlineBlocks && /<(?:ul|ol|li|p|div)\b/i.test(text)) return `<div class="rich-html-block">${content}</div>`;
  return inlineBlocks ? `<span class="rich-inline-text">${content}</span>` : `<p class="rich-paragraph">${content}</p>`;
}

export function renderRichText(value, options = {}) {
  const prepared = prepareRichSource(value, options.inlineBlocks);
  const source = prepared.source;
  if (!source) return '';
  const lines = source.split('\n');
  const blockByMarker = new Map(prepared.blocks.map(block => [block.marker, block]));
  const output = [];
  let paragraph = [];
  let index = 0;
  const flushParagraph = () => {
    const rendered = renderParagraph(paragraph, options.inlineBlocks);
    if (rendered) output.push(rendered);
    paragraph = [];
  };

  while (index < lines.length) {
    const line = lines[index];
    const richBlock = blockByMarker.get(line.trim());
    if (richBlock) {
      flushParagraph();
      output.push(richBlock.html);
      index++;
      continue;
    }
    if (options.tableHtml && line.trim() === '__QUESTION_TABLE_CONTENT__') {
      flushParagraph();
      output.push(options.tableHtml);
      index++;
      continue;
    }
    if (line.trim().startsWith('```')) {
      flushParagraph();
      const code = [];
      index++;
      while (index < lines.length && !lines[index].trim().startsWith('```')) code.push(lines[index++]);
      if (index < lines.length) index++;
      output.push(buildCodeBlockMarkup(dedentCode(code).join('\n'), options.inlineBlocks));
      continue;
    }
    if (isCodeStart(line)) {
      const singleLineCall = /^(?:echo\s*<[^>]+>\s*\(|[A-Za-z_$][\w$]*(?:\.[\w$]+)*\([^)]*\))\s*;?$/.test(line.trim());
      const nextLine = lines[index + 1] ?? '';
      if (singleLineCall && (!nextLine.trim() || !isCodeContinuation(nextLine))) {
        paragraph.push(line.trim());
        index++;
        continue;
      }
      flushParagraph();
      const code = [line];
      index++;
      while (index < lines.length) {
        if (!lines[index].trim()) {
          let lookahead = index + 1;
          while (lookahead < lines.length && !lines[lookahead].trim()) lookahead++;
          if (lookahead < lines.length && (isCodeContinuation(lines[lookahead]) || isCodeStart(lines[lookahead]))) {
            code.push('');
            index++;
            continue;
          }
          break;
        }
        if (!isCodeContinuation(lines[index]) && !isCodeStart(lines[index])) break;
        code.push(lines[index++]);
      }
      output.push(buildCodeBlockMarkup(dedentCode(code).join('\n'), options.inlineBlocks));
      continue;
    }
    if (!line.trim()) {
      flushParagraph();
      index++;
      continue;
    }
    paragraph.push(line);
    index++;
  }
  flushParagraph();
  return output.join('');
}

export const kodeShort = subject => String(subject.kode || '').split('_')[0];

export function subjectPeriod(subject) {
  const code = String(subject?.kode || '');
  const title = String(subject?.judul || '');
  return /(?:^|_)20262$/.test(code) || /(?:^|_)20262$/.test(title) ? '20262' : 'reguler';
}

export function subjectPeriodLabel(subject) {
  return subjectPeriod(subject) === '20262' ? 'Periode 20262' : 'Reguler';
}

// Referensi modul diambil dari tanda kurung terakhir pada penjelasan.
export function moduleRef(question) {
  const matches = [...String(question.penjelasan || '').matchAll(/\(\s*(?:Referensi:\s*)?(Modul\s*\d+[^()<]*?)\s*\)/g)];
  return matches.length ? matches[matches.length - 1][1].replace(/[.\s]+$/, '') : null;
}

export function sourceBlock(question) {
  const reference = moduleRef(question);
  return `<div class="source"><span class="source-label">Sumber</span><span>${reference ? `<b>${escapeHtml(reference)}</b> &middot; ` : ''}${escapeHtml(question.sumber)}</span></div>`;
}

export function subjectParts(subject) {
  const title = String(subject.judul || '');
  const remainder = title.includes(' - ') ? title.split(' - ').slice(1).join(' - ') : title;
  const [name, tag] = remainder.split('_');
  return { name: (name || title).trim(), tag: (tag || '').trim(), period: subjectPeriod(subject) };
}

// Warna aksen per mata kuliah agar daftar panjang lebih mudah dipindai sekilas.
// Deterministik dari kode dasar mata kuliah supaya warna mata kuliah yang sama konsisten antar periode.
const SUBJECT_HUES = 10;
export function subjectHue(subject) {
  const baseCode = String(subject.kode || '').replace(/_20262$/, '');
  let hash = 0;
  for (let i = 0; i < baseCode.length; i++) hash = (hash * 31 + baseCode.charCodeAt(i)) >>> 0;
  return hash % SUBJECT_HUES;
}

export const svg = body => `<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${body}</svg>`;
